SELECT AVG(p.dpi) AS average_dpi FROM (SELECT DISTINCT sp.Product_ID FROM store_product sp JOIN store_district sd ON sp.Store_ID = sd.Store_ID WHERE sd.District_ID = 3) dp JOIN product p ON dp.Product_ID = p.product_id;

